// Applies Smartious' customisations to the generated native projects.
//   node scripts/patch-native.mjs android|ios
// android/ and ios/ are generated by `cap add` (locally or in CI) and never
// committed, so everything native the app needs is written here. Each patch
// is idempotent: running it twice changes nothing.
//
// Env (optional): APP_VERSION_NAME (e.g. 1.0.3), APP_VERSION_CODE (integer,
// must increase with every store upload; CI uses the run number).
import { readFileSync, writeFileSync, existsSync } from 'fs'
import { dirname, resolve } from 'path'
import { fileURLToPath } from 'url'

const here = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const config = JSON.parse(readFileSync(resolve(here, 'capacitor.config.json'), 'utf8'))
const versionName = process.env.APP_VERSION_NAME || '1.0.0'
const versionCode = String(parseInt(process.env.APP_VERSION_CODE || '1', 10) || 1)
const target = process.argv[2]

const edit = (file, fn) => {
  const p = resolve(here, file)
  if (!existsSync(p)) throw new Error(`missing ${file}: run \`npx cap add ${target}\` first`)
  const before = readFileSync(p, 'utf8')
  const after = fn(before)
  if (after !== before) { writeFileSync(p, after); console.log('patched', file) }
}

function android() {
  // Camera + microphone for live classes; Capacitor's WebChromeClient asks
  // for them at runtime when the classroom calls getUserMedia.
  edit('android/app/src/main/AndroidManifest.xml', (xml) => {
    const perms = [
      'android.permission.CAMERA',
      'android.permission.RECORD_AUDIO',
      'android.permission.MODIFY_AUDIO_SETTINGS',
    ]
    const add = perms.filter(p => !xml.includes(`"${p}"`))
      .map(p => `    <uses-permission android:name="${p}" />`)
    if (!xml.includes('android.hardware.camera"'))
      add.push('    <uses-feature android:name="android.hardware.camera" android:required="false" />')
    if (!add.length) return xml
    return xml.replace(/(\s*)<\/manifest>\s*$/, `\n${add.join('\n')}\n</manifest>\n`)
  })

  edit('android/app/build.gradle', (g) => g
    .replace(/versionCode \d+/, `versionCode ${versionCode}`)
    .replace(/versionName "[^"]*"/, `versionName "${versionName}"`))

  // MainActivity: save files the portal generates (reports, exports) to
  // Downloads. The web side hands blob/data downloads to SmartiousAndroid
  // (see frontend/src/lib/appShell.js); plain links go to DownloadManager.
  const pkg = config.appId
  const javaFile = `android/app/src/main/java/${pkg.replace(/\./g, '/')}/MainActivity.java`
  edit(javaFile, () => `package ${pkg};

import android.app.DownloadManager;
import android.content.ContentValues;
import android.content.Context;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.os.Environment;
import android.provider.MediaStore;
import android.util.Base64;
import android.webkit.CookieManager;
import android.webkit.JavascriptInterface;
import android.webkit.URLUtil;
import android.webkit.WebView;
import android.widget.Toast;

import com.getcapacitor.BridgeActivity;

import java.io.File;
import java.io.FileOutputStream;
import java.io.OutputStream;

public class MainActivity extends BridgeActivity {

    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        WebView webView = getBridge().getWebView();
        webView.addJavascriptInterface(new FileSaver(), "SmartiousAndroid");
        webView.setDownloadListener((url, userAgent, contentDisposition, mimeType, contentLength) -> {
            if (url == null || !(url.startsWith("http://") || url.startsWith("https://"))) return;
            String name = URLUtil.guessFileName(url, contentDisposition, mimeType);
            try {
                DownloadManager.Request request = new DownloadManager.Request(Uri.parse(url));
                request.setMimeType(mimeType);
                String cookies = CookieManager.getInstance().getCookie(url);
                if (cookies != null) request.addRequestHeader("Cookie", cookies);
                request.addRequestHeader("User-Agent", userAgent);
                request.setTitle(name);
                request.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);
                request.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS, name);
                DownloadManager dm = (DownloadManager) getSystemService(Context.DOWNLOAD_SERVICE);
                dm.enqueue(request);
                toast("Downloading " + name);
            } catch (Exception e) {
                toast("Couldn't download " + name);
            }
        });
    }

    private void toast(String message) {
        runOnUiThread(() -> Toast.makeText(this, message, Toast.LENGTH_SHORT).show());
    }

    private class FileSaver {
        @JavascriptInterface
        public void save(String base64, String name, String mimeType) {
            try {
                byte[] data = Base64.decode(base64, Base64.DEFAULT);
                String mime = (mimeType == null || mimeType.isEmpty()) ? "application/octet-stream" : mimeType;
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                    ContentValues values = new ContentValues();
                    values.put(MediaStore.Downloads.DISPLAY_NAME, name);
                    values.put(MediaStore.Downloads.MIME_TYPE, mime);
                    Uri uri = getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values);
                    if (uri == null) throw new IllegalStateException("no uri");
                    try (OutputStream out = getContentResolver().openOutputStream(uri)) {
                        out.write(data);
                    }
                } else {
                    File dir = getExternalFilesDir(Environment.DIRECTORY_DOWNLOADS);
                    try (FileOutputStream out = new FileOutputStream(new File(dir, name))) {
                        out.write(data);
                    }
                }
                toast("Saved " + name + " to Downloads");
            } catch (Exception e) {
                toast("Couldn't save " + name);
            }
        }
    }
}
`)
}

function ios() {
  edit('ios/App/App/Info.plist', (plist) => {
    const keys = {
      NSCameraUsageDescription: 'Smartious uses the camera so you can be seen in live classes and upload photos.',
      NSMicrophoneUsageDescription: 'Smartious uses the microphone so you can speak in live classes.',
      NSPhotoLibraryUsageDescription: 'Smartious lets you choose photos and documents to upload, such as homework and certificates.',
      NSPhotoLibraryAddUsageDescription: 'Smartious can save reports and certificates you download to your photo library.',
    }
    let add = ''
    for (const [k, v] of Object.entries(keys))
      if (!plist.includes(`<key>${k}</key>`)) add += `\t<key>${k}</key>\n\t<string>${v}</string>\n`
    plist = plist
      .replace(/(<key>CFBundleShortVersionString<\/key>\s*<string>)[^<]*(<\/string>)/, `$1${versionName}$2`)
      .replace(/(<key>CFBundleVersion<\/key>\s*<string>)[^<]*(<\/string>)/, `$1${versionCode}$2`)
    return add ? plist.replace(/<\/dict>\s*<\/plist>\s*$/, `${add}</dict>\n</plist>\n`) : plist
  })
}

if (target === 'android') android()
else if (target === 'ios') ios()
else { console.error('usage: node scripts/patch-native.mjs android|ios'); process.exit(1) }
